    类型错抛 TypeError；规则数、键序或字段值错抛 PolicyError。
    """
    if not isinstance(rules, list):
        raise TypeError("rules must be list")
    if not 0 <= len(rules) <= _MAX_POLICY_RULES:
        raise PolicyError("rules must contain 0..256 items")
    checked = []
